import React, { useState, useEffect } from 'react';

const Cart = ({ userId }) => {
  const [items, setItems] = useState([]);
  const [error, setError] = useState(null);
  
  // Function to fetch cart data from the API
  const fetchCartData = async () => {
    try {
      console.log('Fetching cart data for user:', userId);
      const response = await fetch(`/api/user?userId=${userId}`);

      // Log the status and raw response text for debugging
      const responseText = await response.text();
      console.log('Response Status:', response.status);
      console.log('Response Text:', responseText);

      // Check if the response is OK (status code 200)
      if (!response.ok) {
        throw new Error(`Failed to fetch data. Status code: ${response.status}`);
      }

      // Try parsing the response as JSON
      try {
        const data = JSON.parse(responseText);
        console.log('Parsed Data:', data);
        
        // Check if the cart data exists and set it
        if (data && data.cart) {
          setItems(data.cart);
        } else {
          setItems([]);
        }
      } catch (parseError) {
        console.error('Error parsing JSON response:', parseError);
        setError('Error parsing cart data');
      }
    } catch (error) {
      console.error('Error fetching cart:', error);
      setError('Error fetching cart data');
    }
  };

  // UseEffect to fetch cart data when the component mounts or userId changes
  useEffect(() => {
    if (userId) {
      fetchCartData();
    }
  }, [userId]);

  return (
    <div className="cart">
      <h1>Your Cart</h1>

      {/* Display error message if there is an error */}
      {error && <div className="error">{error}</div>}

      {/* Display loading state while cart items are being fetched */}
      {items.length === 0 && !error && <p>Loading cart...</p>}

      {/* Render cart items if available */}
      {items.length > 0 && !error && (
        <ul>
          {items.map((item, index) => (
            <li key={index}>
              <img src={item.image} alt={item.name} />
              <h2>{item.name}</h2>
              <p>{item.price}</p>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Cart;
